using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DodgeIncreaseOtherEffectsEffect", menuName = "Data/Battle/Effects/Austra/DodgeIncreaseOtherEffects Effect")]
public class DodgeIncreaseOtherEffectsEffect : Effect
{
	[SerializeField]
	private Effect effectToIncrease;

	[SerializeField]
	private DefaultEffectAction criticalAction;

	protected override string GetLocalizedDescription()
	{
		return "";
	}

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return Smart.Format(base.localizationManager.GetLocalizedWheneverYouDodgeCorruption(), GetCriticalActionDescription(amount));
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(base.localizationManager.GetLocalizedWheneverYouDodgeCorruption(), GetCriticalActionDescription(amount));
	}

	private string GetCriticalActionDescription(int amount)
	{
		if (amount == EffectsValues.NO_VALUE)
		{
			amount = -1;
		}
		return criticalAction.GetActionDescription(amount).LowercaseFirst();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<PlayerEffects>().AddEffect(effectToIncrease, effectAmount);
		return effectAmount;
	}
}
